  "key_technical_decisions": [
    {
      "id": "ADR-001",
      "title": "Optimistic Locking via Version Column for Concurrent Campaign Modifications",
      "status": "Accepted",
      "context": "Brand team members or multiple browser tabs may concurrently edit the same campaign brief or update status. A mechanism is required to prevent lost updates without locking database rows during user think-time.",
      "options_considered": [
        "Pessimistic locking (SELECT FOR UPDATE on fetch): Blocks concurrent readers/writers, risks deadlocks, inappropriate for REST stateless interactions where edits take minutes.",
        "Optimistic locking with integer version: Entity holds version number; update checks WHERE id = :id AND version = :version; increments version to version + 1.",
        "Last-write-wins (no concurrency control): Silently overwrites concurrent edits, causing catastrophic data loss in campaign budgets or brief constraints."
      ],
      "chosen_option": "Optimistic locking with integer version",
      "rationale": "High read-to-write ratio; zero lock overhead during read; provides immediate ConflictError (HTTP 409) if another actor updated the record. Clients can reload the fresh campaign state and merge changes safely."
    },
    {
      "id": "ADR-002",
      "title": "Deterministic Finite State Machine Encapsulated in Service Domain",
      "status": "Accepted",
      "context": "Campaigns undergo a strict lifecycle: draft -> pending_review -> active <-> paused -> completed/cancelled (plus rejected from pending_review with re-edit path). Terminal statuses must be strictly immutable.",
      "options_considered": [
        "Ad-hoc status checks inside individual router endpoints: Fragile, duplicate logic, prone to bypass bugs when adding new endpoints.",
        "Database ENUM check constraints: Validates allowed values but cannot easily enforce transition graphs or conditional business invariants (e.g. budget validation on submit).",
        "Dedicated CampaignStateMachine class in Service layer: Single source of truth defining ALLOWED_TRANSITIONS, state invariants, permitted edits per state, and transition guards."
      ],
      "chosen_option": "Dedicated CampaignStateMachine class in Service layer",
      "rationale": "Centralizes all state machine transitions and guards. Enforces terminal status immutability ('completed' and 'cancelled' cannot transition anywhere). Enforces audit logging atomically whenever a status change occurs."
    },
    {
      "id": "ADR-003",
      "title": "Transactional Append-Only Relational Audit Trail",
      "status": "Accepted",
      "context": "Platform compliance requires an audit trail for every status transition, recording actor, timestamp, from_status, to_status, and reason.",
      "options_considered": [
        "Application logging (stdout/JSON logs parsed by ELK/Datadog): Logs can be dropped, lack transactional atomicity with the database, and cannot be easily queried via REST API.",
        "Dedicated relational table (campaign_status_audit_logs) within the same DB transaction: ACID compliant, foreign-key coupled, trivially queried.",
        "Event streaming to Kafka/Pulsar: Overkill for v1 single-service requirements; introduces distributed dual-write failure modes without an Outbox pattern."
      ],
      "chosen_option": "Dedicated relational table (campaign_status_audit_logs) within the same DB transaction",
      "rationale": "Guarantees zero inconsistency between campaign status and audit logs. If the campaign update fails or is rolled back, the audit record rolls back. Exposes simple queryability for brand and admin audit views."
    },
    {
      "id": "ADR-004",
      "title": "Decoupled Fire-and-Forget Notifications via Celery Tasks",
      "status": "Accepted",
      "context": "Platform admin approval/rejection requires notifying the brand. Campaign cancellation requires notifying participating creators. Requirement states: 'No external service dependencies for CRUD — notification is fire-and-forget via Celery task.'",
      "options_considered": [
        "Synchronous HTTP calls to Notification Service in API handler: Adds latency to HTTP response (500ms+), couples availability of Campaign Service to Notification Service, violates constraint.",
        "Fire-and-forget Celery tasks dispatched after DB transaction commit: Asynchronous, execution offloaded to background workers, automatic retries with backoff, does not block API response.",
        "Transactional Outbox table with polling worker: High reliability but adds extra schema complexity for simple fire-and-forget notifications."
      ],
      "chosen_option": "Fire-and-forget Celery tasks dispatched after DB transaction commit",
      "rationale": "Directly satisfies the non-functional constraint. Keeps API response latency minimal (p95 < 200ms). Celery handles retries with Redis broker without impacting the web server."
    },
    {
      "id": "ADR-005",
      "title": "Composite B-Tree Indexing and Eager Loading Strategy for Sub-200ms p95 SLA",
      "status": "Accepted",
      "context": "Performance constraint dictates: campaign list p95 < 200ms for 10k campaigns per brand.",
      "options_considered": [
        "Default single-column indexes on brand_id, status, created_at: Requires PostgreSQL to perform Bitmap Index Scans and expensive heap sort on 10k rows, resulting in 300-800ms query times under load.",
        "Composite B-Tree indexes matching exact query patterns: (brand_id, is_deleted, status, created_at DESC) and (brand_id, is_deleted, created_at DESC).",
        "Redis read-through cache for all brand lists: High invalidation complexity on campaign updates, memory overhead, redundant for 10k rows if PostgreSQL is properly indexed."
      ],
      "chosen_option": "Composite B-Tree indexes matching exact query patterns with SQLAlchemy selectinload",
      "rationale": "PostgreSQL can execute an Index Only Scan or fast Index Scan directly matching the WHERE and ORDER BY clauses, returning 20 rows in under 4ms for 10,000 campaigns. Avoids N+1 queries by pre-fetching relations in 2 vectorized roundtrips."
    },
    {
      "id": "ADR-006",
      "title": "Normalized 1:1 Tables for Timeline and Eligibility Criteria vs. JSONB",
      "status": "Accepted",
      "context": "Campaign briefs contain complex temporal milestones and creator eligibility rules.",
      "options_considered": [
        "Single campaigns table with JSONB columns for timeline and eligibility: Flexible schema, but makes date range indexing and deadline enforcement queries inefficient.",
        "Normalized 1:1 tables (campaign_timelines, campaign_eligibility_criteria) with strict column types and foreign keys: Strongly typed, foreign keys with CASCADE delete, direct B-Tree indexing on campaign_end_at.",
        "Embedded scalar columns in the campaigns table: Creates a wide table with 25+ columns, polluting the core campaign entity."
      ],
      "chosen_option": "Normalized 1:1 tables (campaign_timelines, campaign_eligibility_criteria) with strict column types and foreign keys",
      "rationale": "Maintains clean domain models. Allows the periodic deadline enforcer to query campaign_timelines.campaign_end_at directly using an index without parsing JSON documents. Enforces strict DB-level type safety."
    },
    {
      "id": "ADR-007",
      "title": "Ownership-Based Authorization via FastAPI CurrentUser Dependency and Service Layer Guards",
      "status": "Accepted",
      "context": "Requirement: 'Security: ownership-based authorization — brands see only own campaigns; admin endpoints require admin role.'",
      "options_considered": [
        "PostgreSQL Row Level Security (RLS): Requires setting session variables on each pooled connection, complex with async connection pools and Celery tasks.",
        "API Gateway URI filter: Ineffective because gateway does not know entity-to-user mappings in the campaign database.",
        "Layered authorization via FastAPI dependency and Service domain check: Gateway validates JWT and forwards X-User-Id/X-User-Roles; FastAPI injects CurrentUser; Service layer enforces campaign.brand_id == current_user.id; Repository enforces brand_id filter in list queries."
      ],
      "chosen_option": "Layered authorization via FastAPI CurrentUser dependency and Service domain check",
      "rationale": "Provides defense in depth, simple unit testing with mock users, and strict consistency with existing User module patterns in xhs-campaign-service."
    }
