    {
      "decision": "Use optimistic locking via integer version field",
      "justification": "Campaign edits are infrequent and conflicts are rare but possible (e.g., two brand team members editing simultaneously). Optimistic locking avoids holding database locks during the user's edit session, which is better for read-heavy workloads.",
      "alternatives_considered": [
        {
          "option": "Pessimistic locking (SELECT ... FOR UPDATE)",
          "rejected_because": "Holds row-level locks during the full edit-save cycle. In a web application the time between reading and writing can be seconds to minutes — this would cause unnecessary lock contention and risk deadlocks."
        },
        {
          "option": "Last-write-wins (no locking)",
          "rejected_because": "Silent data loss when concurrent edits overwrite each other. Unacceptable for campaign budget and deadline fields."
        }
      ],
      "implementation": "Add 'version: int' column with default=1. On update, CampaignService checks version matches, increments it, and uses WHERE version = :expected_version in the UPDATE query. If no rows updated, raise ConflictError."
    },
